```go
package unique_digits_test

import (
	"testing"
	"fmt"
)

// Given a list of positive integers x. return a sorted list of all 
// elements that hasn't any even digit.
// Note: Returned list should be sorted in increasing order.
// For example:
// >>> unique_digits([]int{15, 33, 1422, 1})
// []int{1, 15, 33}
// >>> unique_digits([]int{152, 323, 1422, 10})
// []int{}
func unique_digits(x []int) []int {
	var result []int
	for _, num := range x {
		if hasNoEvenDigit(num) {
			result = append(result, num)
		}
	}
	// Sort the result in increasing order
	for i := 0; i < len(result); i++ {
		for j := i + 1; j < len(result); j++ {
			if result[i] > result[j] {
				result[i], result[j] = result[j], result[i]
			}
		}
	}
	return result
}

func hasNoEvenDigit(n int) bool {
	if n < 0 {
		n = -n
	}
	if n == 0 {
		return false // 0 is even
	}
	for n > 0 {
		digit := n % 10
		if digit%2 == 0 {
			return false
		}
		n /= 10
	}
	return true
}
