// Write a gothon function to find the difference between the sum of cubes of the first n natural numbers and the sum of the first n natural numbers.
func difference(n int) int {
	sumOfCubes := 0
	sumOfNumbers := 0
	for i := 1; i <= n; i++ {
		sumOfCubes += i * i * i
		sumOfNumbers += i
	}
