package find_length_test

import (
    "testing"
    "fmt"
)

// Write a function to find the maximum difference between the number of 0s and number of 1s in any sub-string of the given binary string.
func find_length(myString string) int {
    if len(myString) == 0 {
        return 0
    }

    // Transform the string: replace '0' with +1 and '1' with -1
    // Then find the maximum subarray sum using Kadane's algorithm
    // This gives the maximum difference between count of 0s and count of 1s in any substring

    maxDiff := 0
    currentSum := 0

    for _, ch := range myString {
        val := 0
        if ch == '0' {
            val = 1
        } else if ch == '1' {
            val = -1
        }

        currentSum += val
        if currentSum < 0 {
            currentSum = 0
        }
        if currentSum > maxDiff {
            maxDiff = currentSum
        }
    }

    return maxDiff
}
