// Write a function to find the first adverb and their positions in a given sentence.
func find_adverb_position(text string) []interface{} {
    // Split the text into words and their positions
    words := []string{}
    positions := []int{}

    currentWord := ""
    currentPos := 0

    for i, ch := range text {
        if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
            if currentWord != "" {
                words = append(words, currentWord)
                positions = append(positions, currentPos)
                currentWord = ""
                currentPos = i + 1
            }
        } else {
            if currentWord == "" {
                currentPos = i
            }
            currentWord += string(ch)
        }
    }
    if currentWord != "" {
        words = append(words, currentWord)
        positions = append(positions, currentPos)
    }

    // Check each word to see if it's an adverb (ends with "ly")
    for i, word := range words {
        if len(word) >= 3 && word[len(word)-2:] == "ly" {
            return []interface{}{word, positions[i]}
        }
    }

    return []interface{}{"", -1}
}
