package merge_test

import (
	"testing"
	"fmt"
)

// Write a gothon function which takes a list of lists, where each sublist has two elements, and returns a list of two lists where the first list has the first element of each sublist and the second one has the second.
func merge(lst [][]interface{}) [][]interface{} {
	if len(lst) == 0 {
		return [][]interface{}{[]interface{}{}, []interface{}{}}
	}

	first := make([]interface{}, len(lst))
	second := make([]interface{}, len(lst))

	for i, sub := range lst {
		if len(sub) >= 1 {
			first[i] = sub[0]
		}
		if len(sub) >= 2 {
			second[i] = sub[1]
		}
	}

	return [][]interface{}{first, second}
}
