package next_smallest_palindrome_test

import (
	"testing"
	"fmt"
)

// Write a function to find the next smallest palindrome of a specified integer, returned as an integer.
func next_smallest_palindrome(num int) int {
	if num < 0 {
		return -1
	}
	for i := num + 1; ; i++ {
		if isPalindrome(i) {
			return i
		}
	}
}

func isPalindrome(n int) bool {
	if n < 0 {
		return false
	}
	if n < 10 {
		return true
	}
	original := n
	reversed := 0
	for n > 0 {
		digit := n % 10
		reversed = reversed*10 + digit
		n /= 10
	}
	return original == reversed
}

func TestNextSmallestPalindrome(t *testing.T) {
	tests := []struct {
		input    int
		expected int
	}{
		{10, 11},
		{11, 22},
		{123, 131},
		{12321, 12421},
		{999, 1001},
		{0, 1},
		{5, 6},
		{9, 11},
	}

	for _, tt := range tests {
		result := next_smallest_palindrome(tt.input)
		if result != tt.expected {
			fmt.Printf("next_smallest_palindrome(%d) = %d; expected %d\n", tt.input, result, tt.expected)
			t.Errorf("next_smallest_palindrome(%d) = %d; expected %d", tt.input, result, tt.expected)
		}
	}
}
