func is_sorted(lst []int) bool {
    if len(lst) <= 1 {
        return true
    }

    // Check if sorted in ascending order
    for i := 1; i < len(lst); i++ {
        if lst[i] < lst[i-1] {
            return false
        }
    }

    // Check for duplicates: if any number appears more than once, return false
    // But wait, the examples show:
    // is_sorted([]int{1, 2, 2, 3, 3, 4}) -> true
    // is_sorted([]int{1, 2, 2, 2, 3, 4}) -> false
    // So duplicates are allowed as long as no number appears more than twice? 
    // Let me re-read: "If list has more than 1 duplicate of the same number, return false."
    // "more than 1 duplicate" means more than one occurrence beyond the first? 
    // So if a number appears 3 or more times, return false. If it appears 2 times, it's okay.
    // {1, 2, 2, 3, 3, 4}: 2 appears twice, 3 appears twice -> true
    // {1, 2, 2, 2, 3, 4}: 2 appears three times -> false

    // Count occurrences of each number
    countMap := make(map[int]int)
    for _, num := range lst {
        countMap[num]++
        if countMap[num] > 2 {
            return false
        }
    }

    return true
}
