func order_by_points(nums []int) []int {
	type item struct {
		value int
		index int
	}

	items := make([]item, len(nums))
	for i, v := range nums {
		items[i] = item{value: v, index: i}
	}

	// Sort by sum of digits ascending, then by original index ascending
	for i := 0; i < len(items); i++ {
		for j := i + 1; j < len(items); j++ {
			sumI := sumOfDigits(items[i].value)
			sumJ := sumOfDigits(items[j].value)
			if sumI > sumJ || (sumI == sumJ && items[i].index > items[j].index) {
				items[i], items[j] = items[j], items[i]
			}
		}
	}

	result := make([]int, len(items))
	for i, item := range items {
		result[i] = item.value
	}
	return result
}

func sumOfDigits(n int) int {
	if n < 0 {
		n = -n
	}
	sum := 0
	for n > 0 {
		sum += n % 10
		n /= 10
	}
	return sum
}
