// Write a function to create the next bigger number by rearranging the digits of a given number.
func rearrange_bigger(n int) interface{} {
	// Convert the number to a slice of digits
	digits := []int{}
	temp := n
	if temp == 0 {
		digits = append(digits, 0)
	} else {
		for temp > 0 {
			digits = append(digits, temp%10)
			temp /= 10
		}
	}
	// Reverse to get most significant digit first
	for i, j := 0, len(digits)-1; i < j; i, j = i+1, j-1 {
		digits[i], digits[j] = digits[j], digits[i]
	}

	// Find the first digit from the right that is smaller than its right neighbor
	pivot := -1
	for i := len(digits) - 2; i >= 0; i-- {
		if digits[i] < digits[i+1] {
			pivot = i
			break
		}
	}

	if pivot == -1 {
		// No bigger number possible
		return -1
	}

	// Find the smallest digit to the right of pivot that is larger than digits[pivot]
	succ := -1
	for i := len(digits) - 1; i > pivot; i-- {
		if digits[i] > digits[pivot] {
			succ = i
			break
		}
	}

	// Swap pivot and successor
	digits[pivot], digits[succ] = digits[succ], digits[pivot]

	// Reverse the suffix after pivot to get the smallest arrangement
	for i, j := pivot+1, len(digits)-1; i < j; i, j = i+1, j-1 {
		digits[i], digits[j] = digits[j], digits[i]
	}

	// Convert digits back to number
	result := 0
	for _, d := range digits {
		result = result*10 + d
	}

	return result
}
