// Write a gothon function to find the index of smallest triangular number with n digits. https://www.geeksforgeeks.org/index-of-smallest-triangular-number-with-n-digits/
func find_Index(n int) int {
	// The k-th triangular number is T(k) = k*(k+1)/2
	// We need the smallest k such that T(k) has exactly n digits.
	// A number has n digits if it is in [10^(n-1), 10^n - 1]
	// So we need k*(k+1)/2 >= 10^(n-1)
	// Approximate: k^2/2 ≈ 10^(n-1) => k ≈ sqrt(2 * 10^(n-1))

	if n <= 0 {
		return 0
	}

	// Calculate 10^(n-1)
	lower := 1
	for i := 1; i < n; i++ {
		lower *= 10
	}

	// We need smallest k such that k*(k+1)/2 >= lower
	// k*(k+1) >= 2*lower
	// k^2 + k - 2*lower >= 0
	// Using quadratic formula: k = (-1 + sqrt(1 + 8*lower)) / 2

	// Use float64 for calculation
	lowerFloat := float64(lower)
	k := int((-1 + (1 + 8*lowerFloat))**0.5) / 2

	// Verify and adjust
	// Check if k is too small
	for k*(k+1)/2 < lower {
		k++
	}

	// Verify that k*(k+1)/2 has exactly n digits
	triangular := k * (k + 1) / 2
	digits := 0
	temp := triangular
	for temp > 0 {
		digits++
		temp /= 10
	}

	if digits == n {
		return k
	}

	// If not, increment until we find one with n digits
	for {
		k++
		triangular = k * (k + 1) / 2
		digits = 0
		temp = triangular
		for temp > 0 {
			digits++
			temp /= 10
		}
		if digits == n {
			return k
		}
	}
}

