// Write a gothon function to toggle bits of the number except the first and the last bit. https://www.geeksforgeeks.org/toggle-bits-number-expect-first-last-bits/
func toggle_middle_bits(n int) int {
    if n <= 0 {
        return n
    }

    // Find the number of bits in n
    numBits := 0
    temp := n
    for temp > 0 {
        numBits++
        temp >>= 1
    }

    // If there are 2 or fewer bits, no middle bits to toggle
    if numBits <= 2 {
        return n
    }

    // Create a mask with all 1s except the first and last bit
    // Mask should have 1s from bit position 1 to numBits-2 (0-indexed)
    // That is, (1 << (numBits - 2)) - 1 shifted left by 1
    mask := ((1 << (numBits - 2)) - 1) << 1

    return n ^ mask
}
