// Write a function to calculate the sum of perrin numbers.
func cal_sum(n int) int {
	if n <= 0 {
		return 0
	}

	// Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3) for n>2
	if n == 1 {
		return 3
	}
	if n == 2 {
		return 3 + 0
	}

	// Calculate sum of P(0) through P(n)
	sum := 0
	p0, p1, p2 := 3, 0, 2
	sum += p0 // P(0)
	if n >= 1 {
		sum += p1 // P(1)
	}
	if n >= 2 {
		sum += p2 // P(2)
	}

	for i := 3; i <= n; i++ {
		p3 := p1 + p0
		sum += p3
		p0, p1, p2 = p1, p2, p3
	}

	return sum
}
