func newman_prime(n int) int {
	// Newman-Shanks-Williams numbers are defined by the recurrence:
	// NSW(0) = 1, NSW(1) = 1, NSW(n) = 2*NSW(n-1) + NSW(n-2)
	// We need to find the nth NSW number that is also prime.

	if n <= 0 {
		return 0
	}

	// Generate NSW numbers and check for primality
	count := 0
	a, b := 1, 1 // NSW(0), NSW(1)

	// Check NSW(0) = 1 (not prime)
	// Check NSW(1) = 1 (not prime)
	// Start from NSW(2)

	// Let's generate NSW numbers iteratively
	// NSW(0) = 1
	// NSW(1) = 1
	// NSW(2) = 2*1 + 1 = 3 (prime) -> 1st NSW prime
	// NSW(3) = 2*3 + 1 = 7 (prime) -> 2nd NSW prime
	// NSW(4) = 2*7 + 3 = 17 (prime) -> 3rd NSW prime
	// NSW(5) = 2*17 + 7 = 41 (prime) -> 4th NSW prime
	// NSW(6) = 2*41 + 17 = 99 (not prime)
	// NSW(7) = 2*99 + 41 = 239 (prime) -> 5th NSW prime

	if n == 1 {
		return 3
	}

	// We already know NSW(0)=1, NSW(1)=1 are not prime
	// Start generating from index 2
	prev2 := 1 // NSW(0)
	prev1 := 1 // NSW(1)
	index := 2

	for {
		current := 2*prev1 + prev2
		if isPrime(current) {
			count++
			if count == n {
				return current
			}
		}
		prev2 = prev1
		prev1 = current
		index++
	}
}

func isPrime(num int) bool {
	if num < 2 {
		return false
	}
	if num == 2 {
		return true
	}
	if num%2 == 0 {
		return false
	}
	for i := 3; i*i <= num; i += 2 {
		if num%i == 0 {
			return false
		}
	}
	return true
}
