// Write a function to convert list string to integer list.
func tuple_str_int(test_str string) []interface{} {
    // Parse the string representation of a tuple/list of strings and convert to integers
    // Expected input format: "(str1, str2, str3)" or "[str1, str2, str3]"
    // Each string should be a valid integer representation

    // Remove leading/trailing whitespace
    test_str = trim(test_str)

    // Remove outer brackets/parentheses
    if len(test_str) >= 2 {
        if (test_str[0] == '(' && test_str[len(test_str)-1] == ')') ||
           (test_str[0] == '[' && test_str[len(test_str)-1] == ']') {
            test_str = test_str[1 : len(test_str)-1]
        }
    }

    // Split by comma
    parts := splitByComma(test_str)

    result := make([]interface{}, 0, len(parts))
    for _, part := range parts {
        part = trim(part)
        if part == "" {
            continue
        }
        // Remove quotes if present
        if len(part) >= 2 && part[0] == '"' && part[len(part)-1] == '"' {
            part = part[1 : len(part)-1]
        } else if len(part) >= 2 && part[0] == '\'' && part[len(part)-1] == '\'' {
            part = part[1 : len(part)-1]
        }

        // Convert string to integer
        var val int
        _, err := fmt.Sscanf(part, "%d", &val)
        if err != nil {
            // Try parsing as float and converting to int
            var fval float64
            _, err2 := fmt.Sscanf(part, "%f", &fval)
            if err2 != nil {
                continue
            }
            val = int(fval)
        }
        result = append(result, val)
    }

    return result
}

func trim(s string) string {
    start := 0
    end := len(s)
    for start < end && (s[start] == ' ' || s[start] == '\t' || s[start] == '\n' || s[start] == '\r') {
        start++
    }
    for end > start && (s[end-1] == ' ' || s[end-1] == '\t' || s[end-1] == '\n' || s[end-1] == '\r') {
        end--
    }
    return s[start:end]
}

func splitByComma(s string) []string {
    var parts []string
    current := ""
    inQuotes := false
    quoteChar := byte(0)

    for i := 0; i < len(s); i++ {
        c := s[i]
        if inQuotes {
            if c == quoteChar {
                inQuotes = false
            }
            current += string(c)
        } else {
            if c == '"' || c == '\'' {
                inQuotes = true
                quoteChar = c
                current += string(c)
            } else if c == ',' {
                parts = append(parts, current)
                current = ""
            } else {
                current += string(c)
            }
        }
    }
    if current != "" {
        parts = append(parts, current)
    }
    return parts
}
