		if n&1 == 1 {
			bits = append(bits, '1')
		} else {
			bits = append(bits, '0')
		}
		n >>= 1
	}

	// Reverse the bits
	for i, j := 0, len(bits)-1; i < j; i, j = i+1, j-1 {
		bits[i], bits[j] = bits[j], bits[i]
	}

	result := string(bits)
	if neg {
		result = "-" + result
	}
	return result
}
