package sort_array_test

import (
	"testing"
	"fmt"
	"sort"
)

// Given a list of non-negative integers, return a copy of the given list after sorting,
// you will sort the given list in ascending order if the sum( first index value, last index value) is odd,
// or sort it in descending order if the sum( first index value, last index value) is even.
// Note:
// * don't change the given list.
// Examples:
// >>> sort_array([]int{})
// []int{}
// >>> sort_array([]int{5})
// []int{5}
// >>> sort_array([]int{2, 4, 3, 0, 1, 5})
// []int{0, 1, 2, 3, 4, 5}
// >>> sort_array([]int{2, 4, 3, 0, 1, 5, 6})
// []int{6, 5, 4, 3, 2, 1, 0}
func sort_array(array []int) []int {
	if len(array) == 0 {
		return []int{}
	}

	// Create a copy of the array to avoid modifying the original
	result := make([]int, len(array))
	copy(result, array)

	// Calculate the sum of the first and last elements
	sum := result[0] + result[len(result)-1]

	if sum%2 == 1 {
		// Odd sum: sort in ascending order
		sort.Ints(result)
	} else {
		// Even sum: sort in descending order
		sort.Sort(sort.Reverse(sort.IntSlice(result)))
	}

	return result
}
