	negative := a < 0
	if negative {
		a = -a
	}

	// Find the cube root by binary search
	low := 1
	high := a
	for low <= high {
		mid := low + (high-low)/2
		cube := mid * mid * mid
		if cube == a {
			return true
		} else if cube < a {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}

