// Circular shift the digits of the integer x, shift the digits right by shift
// and return the result as a string.
// If shift > number of digits, return digits reversed.
// >>> circular_shift(12, 1)
// "21"
// >>> circular_shift(12, 2)
// "12"
func circular_shift(x int, shift int) string {
    // Convert the integer to a string to work with digits
    s := fmt.Sprintf("%d", x)
    n := len(s)

    if n == 0 {
        return ""
    }

    // If shift > number of digits, return digits reversed
    if shift > n {
        // Reverse the string
        runes := []rune(s)
        for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
            runes[i], runes[j] = runes[j], runes[i]
        }
        return string(runes)
    }

    // Circular shift right by shift positions
    // A right shift by k means the last k digits move to the front
    // For example, "12345" shifted right by 2 -> "45123"
    effectiveShift := shift % n
    if effectiveShift == 0 {
        return s
    }

    // Split the string: last effectiveShift characters go to the front
    result := s[n-effectiveShift:] + s[:n-effectiveShift]
    return result
}
