package make_palindrome_test

import (
	"testing"
	"fmt"
)

// Find the shortest palindrome that begins with a supplied string.
// Algorithm idea is simple:
// - Find the longest postfix of supplied string that is a palindrome.
// - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
// >>> make_palindrome("")
// ""
// >>> make_palindrome("cat")
// "catac"
// >>> make_palindrome("cata")
// "catac"
func make_palindrome(myString string) string {
	if myString == "" {
		return ""
	}

	// Helper function to check if a string is a palindrome
	isPalindrome := func(s string) bool {
		for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
			if s[i] != s[j] {
				return false
			}
		}
		return true
	}

	// Find the longest palindromic suffix
	for i := 0; i < len(myString); i++ {
		// Check if myString[i:] is a palindrome
		if isPalindrome(myString[i:]) {
			// The prefix before this palindromic suffix is myString[0:i]
			prefix := myString[0:i]
			// Reverse the prefix
			reversedPrefix := reverseString(prefix)
			return myString + reversedPrefix
		}
	}

	// Fallback (should not reach here for non-empty strings)
	return myString + reverseString(myString[:len(myString)-1])
}

// Helper function to reverse a string
func reverseString(s string) string {
