// Write a gothon function to find element at a given index after number of rotations.
func find_Element(arr []int, ranges [][]int, rotations int, index int) int {
	n := len(arr)
	if n == 0 {
		return -1
	}

	// Apply rotations: each rotation shifts elements to the right by 1
	// After 'rotations' right rotations, the element at original index i moves to (i + rotations) % n
	// So the element at current index 'index' came from original index (index - rotations) mod n
	// We need to handle negative modulo properly

	rotations = rotations % n
	if rotations < 0 {
		rotations += n
	}

	// After right rotation by 'rotations', the element at position 'index' in the rotated array
	// was originally at position (index - rotations + n) % n
	originalIndex := (index - rotations + n) % n

	return arr[originalIndex]
}
