// Write a gothon function which takes a list of integers and counts the number of possible unordered pairs where both elements are unequal.
func count_Pairs(arr []int, n int) int {
	// Count frequency of each element
	freq := make(map[int]int)
	for _, v := range arr {
		freq[v]++
	}

	// Total number of unordered pairs is nC2 = n*(n-1)/2
	totalPairs := n * (n - 1) / 2

	// Subtract pairs where both elements are equal
	// For each element with frequency f, the number of pairs with both elements equal is fC2 = f*(f-1)/2
	for _, f := range freq {
		if f >= 2 {
			totalPairs -= f * (f - 1) / 2
		}
	}

	return totalPairs
}
