func magic_square_test(my_matrix [][]int) bool {
	n := len(my_matrix)
	if n == 0 {
		return false
	}
	for _, row := range my_matrix {
		if len(row) != n {
			return false
		}
	}

	// Calculate the target sum from the first row
	targetSum := 0
	for _, val := range my_matrix[0] {
		targetSum += val
	}

	// Check each row sum
	for i := 0; i < n; i++ {
		rowSum := 0
		for j := 0; j < n; j++ {
			rowSum += my_matrix[i][j]
		}
		if rowSum != targetSum {
			return false
		}
	}

	// Check each column sum
	for j := 0; j < n; j++ {
		colSum := 0
		for i := 0; i < n; i++ {
			colSum += my_matrix[i][j]
		}
		if colSum != targetSum {
			return false
		}
	}

	// Check main diagonal sum
	diagSum1 := 0
	for i := 0; i < n; i++ {
		diagSum1 += my_matrix[i][i]
	}
	if diagSum1 != targetSum {
		return false
	}

	// Check anti-diagonal sum
	diagSum2 := 0
	for i := 0; i < n; i++ {
		diagSum2 += my_matrix[i][n-1-i]
	}
	if diagSum2 != targetSum {
		return false
	}

	return true
}
