	var current []rune
	for _, r := range s {
		if r == '_' {
			if len(current) > 0 {
				words = append(words, string(current))
				current = nil
			}
		} else {
			current = append(current, r)
		}
	}
	if len(current) > 0 {
		words = append(words, string(current))
	}
	return words
}

func capitalizeFirst(s string) string {
	if s == "" {
		return ""
	}
