func specialFilter(nums []int) int {
	count := 0
	for _, num := range nums {
		if num <= 10 {
			continue
		}
		// Get the last digit
		lastDigit := num % 10
		// Get the first digit
		temp := num
		for temp >= 10 {
			temp /= 10
		}
		firstDigit := temp
		// Check if both first and last digits are odd
		if firstDigit%2 != 0 && lastDigit%2 != 0 {
			count++
		}
	}
	return count
}
