	}

	// For each element arr[i], it appears in subarrays starting from index j (0 <= j <= i)
	// and ending at index k (i <= k < n).
	// The number of such subarrays is (i + 1) * (n - i).
	// So the contribution of arr[i] to the total sum is arr[i] * (i + 1) * (n - i).
	// This works because the sum of products of all subarrays can be computed by considering
	// each element's contribution. Each subarray's product includes all elements in it,
	// and we can decompose the total sum by each element's multiplicative contribution.
	// Actually, this formula works for the sum of products when we consider that each element
	// arr[i] is multiplied by the number of subarrays it belongs to.

	total := 0
	for i := 0; i < n; i++ {
