package lcs_of_three_test

import (
	"testing"
	"fmt"
)

// Write a function to find the longest common subsequence for the given three string sequence. https://www.geeksforgeeks.org/lcs-longest-common-subsequence-three-strings/
func lcs_of_three(X string, Y string, Z string) int {
	m := len(X)
	n := len(Y)
	p := len(Z)

	// Create a 3D DP array
	dp := make([][][]int, m+1)
	for i := 0; i <= m; i++ {
		dp[i] = make([][]int, n+1)
		for j := 0; j <= n; j++ {
			dp[i][j] = make([]int, p+1)
		}
	}

	// Fill the DP table
	for i := 0; i <= m; i++ {
		for j := 0; j <= n; j++ {
			for k := 0; k <= p; k++ {
				if i == 0 || j == 0 || k == 0 {
					dp[i][j][k] = 0
				} else if X[i-1] == Y[j-1] && Y[j-1] == Z[k-1] {
					dp[i][j][k] = dp[i-1][j-1][k-1] + 1
				} else {
					dp[i][j][k] = max3(
						dp[i-1][j][k],
						dp[i][j-1][k],
						dp[i][j][k-1],
					)
				}
			}
		}
	}

	return dp[m][n][p]
}

func max3(a, b, c int) int {
	if a >= b && a >= c {
		return a
	}
	if b >= a && b >= c {
		return b
	}
	return c
}
