func change_base(x int, base int) string {
	if x == 0 {
		return "0"
	}

	negative := false
	if x < 0 {
		negative = true
		x = -x
	}

	digits := "0123456789"
	var result []byte

	for x > 0 {
		remainder := x % base
		result = append(result, digits[remainder])
		x /= base
	}

	// Reverse the result
	for i, j := 0, len(result)-1; i < j; i, j = i+1, j-1 {
		result[i], result[j] = result[j], result[i]
	}

	if negative {
		return "-" + string(result)
	}
	return string(result)
}
