// 11
// >>> skjkasdkd([]int{0, 81, 12, 3, 1, 21})
// 3
// >>> skjkasdkd([]int{0, 8, 1, 2, 1, 7})
// 7
func skjkasdkd(lst []int) int {
	isPrime := func(n int) bool {
		if n < 2 {
			return false
		}
		if n == 2 {
			return true
		}
		if n%2 == 0 {
			return false
		}
		for i := 3; i*i <= n; i += 2 {
			if n%i == 0 {
				return false
			}
		}
		return true
	}

	sumDigits := func(n int) int {
		sum := 0
		for n > 0 {
			sum += n % 10
			n /= 10
		}
		return sum
	}

	largestPrime := -1
	for _, num := range lst {
		if isPrime(num) && num > largestPrime {
			largestPrime = num
		}
	}

	if largestPrime == -1 {
		return 0
	}

	return sumDigits(largestPrime)
}
