package bf_test

import (
	"testing"
	"fmt"
)

// There are eight planets in our solar system: the closerst to the Sun 
// is Mercury, the next one is Venus, then Earth, Mars, Jupiter, Saturn, 
// Uranus, Neptune.
// Write a function that takes two planet names as strings planet1 and planet2. 
// The function should return a list containing all planets whose orbits are 
// located between the orbit of planet1 and the orbit of planet2, sorted by 
// the proximity to the sun. 
// The function should return an empty list if planet1 or planet2
// are not correct planet names. 
// Examples
// >>> bf("Jupiter", "Neptune")
// []interface{}{"Saturn", "Uranus"}
// >>> bf("Earth", "Mercury")
// "Venus"
// >>> bf("Mercury", "Uranus")
// []interface{}{"Venus", "Earth", "Mars", "Jupiter", "Saturn"}
func bf(planet1 string, planet2 string) []interface{} {
	planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}

	// Find indices of planet1 and planet2
	idx1 := -1
	idx2 := -1
	for i, p := range planets {
		if p == planet1 {
			idx1 = i
		}
		if p == planet2 {
			idx2 = i
		}
	}

	// If either planet is not found, return empty list
	if idx1 == -1 || idx2 == -1 {
		return []interface{}{}
	}

	// Determine the start and end indices (inclusive of boundaries, but we want planets BETWEEN)
	start := idx1
	end := idx2

	// Ensure start < end
	if start > end {
		start, end = end, start
	}

	// Collect planets between start and end (exclusive of start and end)
	var result []interface{}
	for i := start + 1; i < end; i++ {
		result = append(result, planets[i])
	}

	return result
}
