// Write a function to convert rgb color to hsv color. https://www.geeksforgeeks.org/program-change-rgb-color-model-hsv-color-model/
func rgb_to_hsv(r int, g int, b int) []float64 {
	rNorm := float64(r) / 255.0
	gNorm := float64(g) / 255.0
	bNorm := float64(b) / 255.0

	maxVal := rNorm
	if gNorm > maxVal {
		maxVal = gNorm
	}
	if bNorm > maxVal {
		maxVal = bNorm
	}

	minVal := rNorm
	if gNorm < minVal {
		minVal = gNorm
	}
	if bNorm < minVal {
		minVal = bNorm
	}

	v := maxVal

	delta := maxVal - minVal

	if maxVal == 0 {
		return []float64{0, 0, 0}
	}

	s := delta / maxVal

	var h float64
	if delta == 0 {
		h = 0
	} else if maxVal == rNorm {
		h = 60 * ((gNorm-bNorm)/delta)
	} else if maxVal == gNorm {
		h = 60 * ((bNorm-rNorm)/delta + 2)
	} else {
		h = 60 * ((rNorm-gNorm)/delta + 4)
	}

	if h < 0 {
		h += 360
	}

	return []float64{h, s, v}
}
