func is_perfect_square(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 || n == 1 {
		return true
	}
	// Binary search for the square root
	low := 1
	high := n / 2
	for low <= high {
		mid := low + (high-low)/2
		sq := mid * mid
		if sq == n {
			return true
		} else if sq < n {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}
	return false
}
