// Write a function to sort a list of elements.
func pancake_sort(nums []int) []int {
	// Make a copy to avoid modifying the original slice
	arr := make([]int, len(nums))
	copy(arr, nums)

	n := len(arr)
	for currSize := n; currSize > 1; currSize-- {
		// Find the index of the maximum element in arr[0:currSize]
		maxIdx := 0
		for i := 1; i < currSize; i++ {
			if arr[i] > arr[maxIdx] {
				maxIdx = i
			}
		}

		// If the maximum element is not already at the end
		if maxIdx != currSize-1 {
			// Flip the array from 0 to maxIdx to bring the max element to the front
			if maxIdx > 0 {
				reverse(arr, 0, maxIdx)
			}
			// Flip the array from 0 to currSize-1 to move the max element to its correct position
			reverse(arr, 0, currSize-1)
		}
	}

	return arr
}

// reverse reverses the elements in arr from index i to j (inclusive)
func reverse(arr []int, i, j int) {
	for i < j {
		arr[i], arr[j] = arr[j], arr[i]
		i++
		j--
	}
}
