// Write a function to find the length of the longest palindromic subsequence in the given string.
func lps(str string) int {
	n := len(str)
	if n == 0 {
		return 0
	}

	// dp[i][j] represents the length of the longest palindromic subsequence in str[i..j]
	dp := make([][]int, n)
	for i := range dp {
		dp[i] = make([]int, n)
	}

	// Every single character is a palindrome of length 1
	for i := 0; i < n; i++ {
		dp[i][i] = 1
	}

	// Fill the table for substrings of length 2 to n
	for cl := 2; cl <= n; cl++ {
		for i := 0; i < n-cl+1; i++ {
			j := i + cl - 1
			if str[i] == str[j] && cl == 2 {
				dp[i][j] = 2
			} else if str[i] == str[j] {
				dp[i][j] = dp[i+1][j-1] + 2
			} else {
				dp[i][j] = max(dp[i+1][j], dp[i][j-1])
			}
		}
	}

	return dp[0][n-1]
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
