// Write a function to find the Eulerian number a(n, m).
func eulerian_num(n int, m int) int {
	if n < 0 || m < 0 || m >= n {
		return 0
	}
	if n == 0 && m == 0 {
		return 1
	}
	if n == 1 && m == 0 {
		return 1
	}
	// Use dynamic programming
	// a(n, m) = (m+1) * a(n-1, m) + (n-m) * a(n-1, m-1)
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}
	dp[0][0] = 1
	for i := 1; i <= n; i++ {
		for j := 0; j < i; j++ {
			dp[i][j] = (j+1)*dp[i-1][j] + (i-j)*dp[i-1][j-1]
		}
	}
	return dp[n][m]
}
