	// We need to handle multiple delimiters and extract sentences
	var sentences []string
	var current strings.Builder

	for _, ch := range S {
		if ch == '.' || ch == '?' || ch == '!' {
			sentence := strings.TrimSpace(current.String())
			if sentence != "" {
				sentences = append(sentences, sentence)
			}
			current.Reset()
		} else {
			current.WriteRune(ch)
		}
	}

	// Handle the last sentence if there's no trailing delimiter
	lastSentence := strings.TrimSpace(current.String())
	if lastSentence != "" {
		sentences = append(sentences, lastSentence)
	}

	count := 0
	for _, sentence := range sentences {
		// Check if the sentence starts with "I"
		// We need to check if the first word is exactly "I"
		words := strings.Fields(sentence)
		if len(words) > 0 && words[0] == "I" {
			count++
		}
	}

