func find_kth(arr1 []int, arr2 []int, k int) int {
	// Edge case: k is out of bounds
	if k < 1 || k > len(arr1)+len(arr2) {
		panic("k is out of bounds")
	}

	// Use binary search approach to find the kth element in O(log(min(m,n))) time
	// Ensure arr1 is the smaller array for efficiency
	if len(arr1) > len(arr2) {
		return find_kth(arr2, arr1, k)
	}

	m, n := len(arr1), len(arr2)

	// Binary search on the smaller array
	left, right := 0, m
	for left <= right {
		i := (left + right) / 2
		j := k - i

		// Handle edge cases where i or j is at boundaries
		var arr1Left, arr1Right, arr2Left, arr2Right int

		if i == 0 {
			arr1Left = int(^uint(0) >> 1) // max int
		} else {
			arr1Left = arr1[i-1]
		}

		if i == m {
			arr1Right = int(^uint(0) >> 1) // max int
		} else {
			arr1Right = arr1[i]
		}

		if j == 0 {
			arr2Left = int(^uint(0) >> 1) // max int
		} else {
			arr2Left = arr2[j-1]
		}

		if j == n {
			arr2Right = int(^uint(0) >> 1) // max int
		} else {
			arr2Right = arr2[j]
		}

		if arr1Left <= arr2Right && arr2Left <= arr1Right {
			// Found the correct partition
			if i == 0 {
				return arr2Left
			}
			if j == 0 {
				return arr1Left
			}
			return max(arr1Left, arr2Left)
		} else if arr1Left > arr2Right {
			// Move left in arr1
			right = i - 1
		} else {
			// Move right in arr1
			left = i + 1
		}
	}

	panic("kth element not found")
}

