	}

	n := len(arr)
	// dp[i] stores the maximum product of an increasing subsequence ending at index i
	dp := make([]int, n)
	for i := 0; i < n; i++ {
		dp[i] = arr[i]
	}

	maxProd := arr[0]
	for i := 1; i < n; i++ {
		for j := 0; j < i; j++ {
			if arr[j] < arr[i] {
				if dp[j]*arr[i] > dp[i] {
					dp[i] = dp[j] * arr[i]
				}
			}
		}
		if dp[i] > maxProd {
			maxProd = dp[i]
		}
	}

	return maxProd
}
