// Write a function to find the median of two sorted lists of same size.
func get_median(arr1 []int, arr2 []int, n int) float64 {
	// Merge the two sorted arrays into one sorted array
	merged := make([]int, 2*n)
	i, j, k := 0, 0, 0
	for i < n && j < n {
		if arr1[i] <= arr2[j] {
			merged[k] = arr1[i]
			i++
		} else {
			merged[k] = arr2[j]
			j++
		}
		k++
	}
	for i < n {
		merged[k] = arr1[i]
		i++
		k++
	}
	for j < n {
		merged[k] = arr2[j]
		j++
		k++
	}

	// Find the median of the merged array
	if 2*n%2 == 0 {
		return float64(merged[n-1]+merged[n])/2.0
	}
	return float64(merged[n])
}
