// >>> reverse_delete("abcde", "ae")
// []interface{}{"bcd", false}
// >>> reverse_delete("abcdef", "b")
// []interface{}{"acdef", false}
// >>> reverse_delete("abcdedcba", "ab")
// []interface{}{"cdedc", true}
func reverse_delete(s string, c string) []interface{} {
	// Build a set of characters to delete
	deleteSet := make(map[rune]bool)
	for _, ch := range c {
		deleteSet[ch] = true
	}

	// Build the result string by removing characters in c
	var result []rune
	for _, ch := range s {
		if !deleteSet[ch] {
			result = append(result, ch)
		}
	}

	resultStr := string(result)

	// Check if the result string is a palindrome
	isPalindrome := true
	n := len(resultStr)
	for i := 0; i < n/2; i++ {
		if resultStr[i] != resultStr[n-1-i] {
			isPalindrome = false
			break
		}
	}

	return []interface{}{resultStr, isPalindrome}
}
