package minPath_test

import (
	"container/heap"
)

// Given a grid with N rows and N columns (N >= 2) and a positive integer k, 
// each cell of the grid contains a value. Every integer in the range [1, N * N]
// inclusive appears exactly once on the cells of the grid.
// You have to find the minimum path of length k in the grid. You can start
// from any cell, and in each step you can move to any of the neighbor cells,
// in other words, you can go to cells which share an edge with you current
// cell.
// Please note that a path of length k means visiting exactly k cells (not
// necessarily distinct).
// You CANNOT go off the grid.
// A path A (of length k) is considered less than a path B (of length k) if
// after making the ordered lists of the values on the cells that A and B go
// through (let's call them lst_A and lst_B), lst_A is lexicographically less
// than lst_B, in other words, there exist an integer index i (1 <= i <= k)
// such that lst_A[i] < lst_B[i] and for any j (1 <= j < i) we have
// lst_A[j] = lst_B[j].
// It is guaranteed that the answer is unique.
// Return an ordered list of the values on the cells that the minimum path go through.
// Examples:    
// >>> minPath([][]int{[]int{1, 2, 3}, []int{4, 5, 6}, []int{7, 8, 9}}, 3)
// []int{1, 2, 1}
// >>> minPath([][]int{[]int{5, 9, 3}, []int{4, 1, 6}, []int{7, 8, 2}}, 1)
// []int{1}
func minPath(grid [][]int, k int) []int {
	n := len(grid)

	// Find the position of each value for quick lookup
	// We need to find the lexicographically smallest path of length k.
	// Since we want the lexicographically smallest path, we should start with the smallest possible first element.
	// The smallest value in the grid is 1. So the first element of the path must be 1.
	// Then from that cell, we need to find the lexicographically smallest path of length k-1 starting from a neighbor.

	// Find position of value 1
	startR, startC := -1, -1
	for r := 0; r < n; r++ {
		for c := 0; c < n; c++ {
			if grid[r][c] == 1 {
				startR, startC = r, c
				break
			}
		}
		if startR != -1 {
			break
		}
	}

	// BFS/Dijkstra-like approach: we want the lexicographically smallest path.
	// At each step, we want to pick the neighbor with the smallest value.
	// But wait - it's not just greedy. We need to consider that picking a slightly larger value now might lead to a much smaller value later.
	// However, for lexicographic comparison, the first differing element matters most.
	// So at each step, we should pick the smallest possible value at the current position, given the prefix so far.
	// This is actually a greedy approach: at each step, among all reachable cells at that step, pick the one with the smallest value.
	// But we need to ensure that from that cell, we can complete a path of the remaining length.
	// Since we can revisit cells and the grid is connected (it's a grid graph), we can always complete the path as long as there's at least one neighbor.
	// For k=1, the answer is just [1].
	// For k>1, we start at the cell with value 1, then at each step move to the neighbor with the smallest value.

	// Let's verify with the example:
	// grid = [[1,2,3],[4,5,6],[7,8,9]], k=3
	// Start at (0,0) with value 1.
	// Neighbors of (0,0): (0,1) with value 2, (1,0) with value 4.
	// Smallest is 2 at (0,1).
	// From (0,1), neighbors: (0,0) with value 1, (0,2) with value 3, (1,1) with value 5.
	// Smallest is 1 at (0,0).
	// Path: [1, 2, 1]. This matches the expected output.

	// Another example: grid = [[5,9,3],[4,1,6],[7,8,2]], k=1
	// Start at cell with value 1, which is (1,1). Path: [1]. Matches.

	// So the greedy approach works: start at the cell with value 1, then at each step move to the neighbor with the smallest value.

	result := make([]int, k)
	result[0] = 1
	r, c := startR, startC

	for i := 1; i < k; i++ {
		// Find the neighbor with the smallest value
		minVal := n * n + 1
		minR, minC := -1, -1
		// Directions: up, down, left, right
		dirs := []struct{ dr, dc int }{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
		for _, d := range dirs {
			nr, nc := r+d.dr, c+d.dc
			if nr >= 0 && nr < n && nc >= 0 && nc < n {
				if grid[nr][nc] < minVal {
					minVal = grid[nr][nc]
					minR, minC = nr, nc
				}
			}
		}
		result[i] = minVal
		r, c = minR, minC
	}

	return result
}
