func max_sum_increasing_subseq(a []int, n int, index int, k int) int {
	if index < 0 || k >= n || k <= index {
		return 0
	}

	// We need to find the maximum sum increasing subsequence ending at some index i (0 <= i <= index)
	// such that a[i] < a[k], and then add a[k] to that sum.
	// If no such i exists, the subsequence is just [a[k]].

	// dp[i] = maximum sum of increasing subsequence ending at index i
	dp := make([]int, n)
	for i := 0; i < n; i++ {
		dp[i] = a[i]
	}

	for i := 1; i < n; i++ {
		for j := 0; j < i; j++ {
			if a[j] < a[i] && dp[j]+a[i] > dp[i] {
				dp[i] = dp[j] + a[i]
			}
		}
	}

	// Now find the maximum dp[i] for i in [0, index] where a[i] < a[k]
	maxSum := 0
	found := false
	for i := 0; i <= index; i++ {
		if a[i] < a[k] {
			if !found || dp[i] > maxSum {
				maxSum = dp[i]
			}
			found = true
		}
	}

	if !found {
		return a[k]
	}

	return maxSum + a[k]
}
