// Write a function to check for the number of jumps required of given length to reach a point of form (d, 0) from origin in a 2d plane.
func min_Jumps(steps []interface{}, d int) float64 {
	// Extract the jump lengths from the interface slice
	var jumpLengths []float64
	for _, step := range steps {
		switch v := step.(type) {
		case int:
			jumpLengths = append(jumpLengths, float64(v))
		case float64:
			jumpLengths = append(jumpLengths, v)
		case int64:
			jumpLengths = append(jumpLengths, float64(v))
		default:
			// Skip unsupported types
			continue
		}
	}

	// If no valid jump lengths, return 0
	if len(jumpLengths) == 0 {
		return 0
	}

	// The problem is to find the minimum number of jumps to reach (d, 0) from (0, 0)
	// Each jump can be in any direction with the given lengths.
	// This is equivalent to: can we form a polygon (or degenerate polygon) where the sum of some subset of jumps equals d?
	// Actually, in 2D plane, with jumps of given lengths, we can reach (d, 0) if and only if:
	// 1. The sum of all jump lengths >= d (triangle inequality generalized)
	// 2. The largest jump length <= sum of all other jump lengths + d (but since we can choose direction, it's simpler)

	// Actually, the key insight: with jumps of lengths l1, l2, ..., ln, we can reach distance d from origin if and only if:
	// - d <= sum of all lengths (we can always orient jumps to add up)
	// - And we need at least enough "reach"

	// But the question asks for the MINIMUM number of jumps. So we want the smallest k such that we can pick k jumps whose lengths can sum to d (in terms of vector addition in 2D).

	// In 2D, with k jumps of lengths l1, l2, ..., lk, we can reach any point within distance sum(li) from origin, and the reachable region is an annulus if the largest li > sum of others, otherwise it's a disk.
	// Specifically, we can reach distance d if and only if:
	// max(0, 2*max(li) - sum(li)) <= d <= sum(li)

	// We want the minimum k such that there exists a subset of k jumps satisfying the above.

	// Let's try all possible subset sizes from 1 to len(jumpLengths)
	for k := 1; k <= len(jumpLengths); k++ {
		// Check if any subset of size k can reach distance d
		// For efficiency, we can use a greedy approach or dynamic programming
		// But for correctness, let's think: for a fixed subset, the condition is:
		// Let S = sum of lengths in subset, M = max length in subset
		// We can reach d iff M <= S - M + d ... no, the condition is:
		// We can form a polygon with sides l1,...,lk and closing side d iff each li <= sum of others + d... 
		// Actually, the condition to reach exactly distance d with k jumps is:
		// d <= sum(li) and d >= max(0, 2*M - sum(li)) where M is the maximum jump length in the subset

		// To minimize k, we should try to use the largest jumps first to maximize sum and minimize the gap.
		// Sort jumpLengths in descending order
		sorted := make([]float64, len(jumpLengths))
		copy(sorted, jumpLengths)
		// Sort descending
		for i := 0; i < len(sorted); i++ {
			for j := i + 1; j < len(sorted); j++ {
				if sorted[j] > sorted[i] {
					sorted[i], sorted[j] = sorted[j], sorted[i]
				}
			}
		}

		// Try subsets of size k using the largest k jumps (greedy: largest jumps give most reach)
		// Actually, we need to check if ANY subset of size k works. But using largest jumps is optimal for maximizing sum.
		// For a subset of size k, the best chance is to use the k largest jumps.
		if k > len(sorted) {
			break
		}

		sumK := 0.0
		maxK := 0.0
		for i := 0; i < k; i++ {
			sumK += sorted[i]
			if sorted[i] > maxK {
				maxK = sorted[i]
			}
		}

		// Check if d is reachable with these k jumps
		minReach := maxK - (sumK - maxK) // = 2*maxK - sumK, but floored at 0
		if minReach < 0 {
			minReach = 0
		}

		if d >= minReach && d <= sumK {
			return float64(k)
		}
	}

	// If not reachable with any subset, return -1 or 0
	return -1
}
