func sum_in_range(l int, r int) int {
	// Ensure l <= r
	if l > r {
		l, r = r, l
	}

	// Find the first odd number >= l
	start := l
	if start%2 == 0 {
		start++
	}

	// Find the last odd number <= r
	end := r
	if end%2 == 0 {
		end--
	}

	// If no odd numbers in range
	if start > end {
		return 0
	}

	// Number of terms in the arithmetic sequence
	n := (end-start)/2 + 1

	// Sum of arithmetic sequence: n/2 * (first + last)
	sum := n * (start + end) / 2

	return sum
