package do_algebra_test

import (
	"testing"
	"fmt"
)

// Given two lists operator, and operand. The first list has basic algebra operations, and 
// the second list is a list of integers. Use the two given lists to build the algebric 
// expression and return the evaluation of this expression.
// The basic algebra operations:
// Addition ( + ) 
// Subtraction ( - ) 
// Multiplication ( * ) 
// Floor division ( // ) 
// Exponentiation ( ** ) 
// Example:
// operator['+', '*', '-']
// list = [2, 3, 4, 5]
// result = 2 + 3 * 4 - 5
// => result = 9
// Note:
// The length of operator list is equal to the length of operand list minus one.
// Operand is a list of of non-negative integers.
// Operator list has at least one operator, and operand list has at least two operands.
func do_algebra(operator []string, operand []int) int {
	// We need to evaluate the expression respecting operator precedence.
	// Precedence: ** (highest), then *, //, then +, - (lowest)
	// We'll use a two-pass approach: first handle ** and *, //, then + and -.

	// First, handle exponentiation (**)
	// We'll build a new list of operands and operators, processing ** first.
	operands := make([]int, len(operand))
	copy(operands, operand)
	ops := make([]string, len(operator))
	copy(ops, operator)

	// Process exponentiation
	i := 0
	for i < len(ops) {
		if ops[i] == "**" {
			result := 1
			base := operands[i]
			exp := operands[i+1]
			// Compute base^exp
			for j := 0; j < exp; j++ {
				result *= base
			}
			// Remove the two operands and the operator, replace with result
			// Shift elements
			newOperands := make([]int, len(operands)-1)
			newOps := make([]string, len(ops)-1)
			copy(newOperands, operands[:i])
			newOperands[i] = result
			copy(newOperands[i+1:], operands[i+2:])
			copy(newOps, ops[:i])
			copy(newOps[i:], ops[i+1:])
			operands = newOperands
			ops = newOps
			// Don't increment i, check again at same position
		} else {
			i++
		}
	}

	// Process multiplication (*) and floor division (//)
	i = 0
	for i < len(ops) {
		if ops[i] == "*" || ops[i] == "//" {
			var result int
			if ops[i] == "*" {
				result = operands[i] * operands[i+1]
			} else {
				// Floor division: for non-negative integers, regular division works
				result = operands[i] / operands[i+1]
			}
			newOperands := make([]int, len(operands)-1)
			newOps := make([]string, len(ops)-1)
			copy(newOperands, operands[:i])
			newOperands[i] = result
			copy(newOperands[i+1:], operands[i+2:])
			copy(newOps, ops[:i])
			copy(newOps[i:], ops[i+1:])
			operands = newOperands
			ops = newOps
			// Don't increment i
		} else {
			i++
		}
	}

	// Process addition (+) and subtraction (-)
	i = 0
	for i < len(ops) {
		if ops[i] == "+" || ops[i] == "-" {
			var result int
			if ops[i] == "+" {
				result = operands[i] + operands[i+1]
			} else {
				result = operands[i] - operands[i+1]
			}
			newOperands := make([]int, len(operands)-1)
			newOps := make([]string, len(ops)-1)
			copy(newOperands, operands[:i])
			newOperands[i] = result
			copy(newOperands[i+1:], operands[i+2:])
			copy(newOps, ops[:i])
			copy(newOps[i:], ops[i+1:])
			operands = newOperands
			ops = newOps
			// Don't increment i
		} else {
			i++
		}
	}

	return operands[0]
}
