package get_closest_vowel_test

import (
	"testing"
	"fmt"
)

// You are given a word. Your task is to find the closest vowel that stands between 
// two consonants from the right side of the word (case sensitive).
// Vowels in the beginning and ending doesn't count. Return empty string if you didn't
// find any vowel met the above condition. 
// You may assume that the given string contains English letter only.
// Example:
// >>> get_closest_vowel("yogurt")
// "u"
// >>> get_closest_vowel("FULL")
// "U"
// >>> get_closest_vowel("quick")
// ""
// >>> get_closest_vowel("ab")
// ""
func get_closest_vowel(word string) string {
	if len(word) < 3 {
		return ""
	}

	isVowel := func(c byte) bool {
		switch c {
		case 'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U':
			return true
		default:
			return false
		}
	}

	isConsonant := func(c byte) bool {
		return !isVowel(c) && (c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z')
	}

	// We need to find a vowel that is between two consonants, scanning from the right.
	// The vowel cannot be at the beginning (index 0) or at the end (index len-1).
	// So we look at indices 1 to len-2.
	// We want the closest vowel from the right side, so we scan from right to left.

	for i := len(word) - 2; i >= 1; i-- {
		if isVowel(word[i]) {
			// Check if the character before and after are consonants
			if isConsonant(word[i-1]) && isConsonant(word[i+1]) {
				return string(word[i])
			}
		}
	}

	return ""
}
