// Write a function that takes in a sorted list, its length (n), and an element and returns whether the element is the majority element in the given sorted list. (The majority element is the element that occurs more than n/2 times.)
func is_majority(arr []int, n int, x int) bool {
	if n == 0 {
		return false
	}

	// Find the first occurrence of x using binary search
	low, high := 0, n-1
	first := -1
	for low <= high {
		mid := low + (high-low)/2
		if arr[mid] == x {
			first = mid
			high = mid - 1
		} else if arr[mid] < x {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}

	if first == -1 {
		return false
	}

	// Find the last occurrence of x using binary search
	low, high = 0, n-1
	last := -1
	for low <= high {
		mid := low + (high-low)/2
		if arr[mid] == x {
			last = mid
			low = mid + 1
		} else if arr[mid] < x {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}

	if last == -1 {
		return false
	}

	count := last - first + 1
	return count > n/2
}
