package bell_number_test

import (
	"testing"
	"fmt"
)

// Write a function to find the number of ways to partition a set of Bell numbers.
func bell_number(n int) int {
	if n < 0 {
		return 0
	}
	if n == 0 {
		return 1
	}

	// Bell numbers can be computed using the Bell triangle (Aitken's array)
	// or using the recurrence: B(n+1) = sum_{k=0}^{n} C(n,k) * B(k)
	// We'll use the triangle method for efficiency.

	// Create a 2D array for the Bell triangle
	// triangle[i][j] represents the j-th element in the i-th row
	// The first element of each row is the last element of the previous row
	// Each subsequent element is the sum of the previous element in the same row and the element above-left

	// We only need the previous row to compute the current row
	// So we can optimize space

	// Initialize with B(0) = 1
	prevRow := []int{1}

	for i := 1; i <= n; i++ {
		// Compute the next row
		nextRow := make([]int, i+1)
		nextRow[0] = prevRow[len(prevRow)-1] // First element is last of previous row
		for j := 1; j <= i; j++ {
			nextRow[j] = nextRow[j-1] + prevRow[j-1]
		}
		prevRow = nextRow
	}

	return prevRow[len(prevRow)-1]
}
```

