func move_zero(num_list []int) []int {
	// Create a copy to avoid modifying the original slice
	result := make([]int, len(num_list))
	zeroCount := 0
	idx := 0

	// First pass: copy all non-zero elements
	for _, num := range num_list {
		if num != 0 {
			result[idx] = num
			idx++
