package is_decimal_test

import (
	"testing"
	"fmt"
)

// Write a function to check whether a given string is a decimal number with a precision of 2.
func is_decimal(num string) bool {
	if num == "" {
		return false
	}

	// Check for optional leading minus sign
	start := 0
	if num[0] == '-' {
		start = 1
	}

	if start >= len(num) {
		return false
	}

	// Find the decimal point
	dotIndex := -1
	for i := start; i < len(num); i++ {
		if num[i] == '.' {
			dotIndex = i
			break
		}
	}

	if dotIndex == -1 {
		// No decimal point, not a decimal with precision 2
		return false
	}

	// Check that there is exactly one decimal point
	for i := dotIndex + 1; i < len(num); i++ {
		if num[i] == '.' {
			return false
		}
	}

	// Check that there are exactly 2 digits after the decimal point
	afterDot := len(num) - dotIndex - 1
	if afterDot != 2 {
		return false
	}

	// Check that all characters before the decimal point (after optional minus) are digits
	for i := start; i < dotIndex; i++ {
		if num[i] < '0' || num[i] > '9' {
			return false
		}
	}

	// Check that all characters after the decimal point are digits
	for i := dotIndex + 1; i < len(num); i++ {
		if num[i] < '0' || num[i] > '9' {
			return false
		}
	}

	// Ensure there is at least one digit before the decimal point
	if dotIndex == start {
		return false
	}

	return true
}
