// Given a positive integer n, return the count of the numbers of n-digit
// positive integers that start or end with 1.
func starts_one_ends(n int) int {
    if n == 1 {
        return 1
    }
    // n-digit numbers range from 10^(n-1) to 10^n - 1
    // Numbers starting with 1: 10^(n-1) to 2*10^(n-1) - 1, which is 10^(n-1) numbers
    // Numbers ending with 1: For each of the first n-1 digits (first digit 1-9, others 0-9),
    //   the last digit is fixed as 1. So there are 9 * 10^(n-2) such numbers.
    // Numbers both starting and ending with 1: First digit is 1, last digit is 1, middle n-2 digits are 0-9.
    //   So there are 10^(n-2) such numbers.
    // By inclusion-exclusion: start_with_1 + end_with_1 - both
    // = 10^(n-1) + 9*10^(n-2) - 10^(n-2)
    // = 10^(n-1) + 8*10^(n-2)
    // = 10*10^(n-2) + 8*10^(n-2)
    // = 18*10^(n-2)

    // Let's verify for n=2: 18*10^0 = 18. Two-digit numbers starting or ending with 1:
    // Starting with 1: 10-19 (10 numbers)
    // Ending with 1: 11,21,31,41,51,61,71,81,91 (9 numbers)
    // Both: 11 (1 number)
    // Total: 10 + 9 - 1 = 18. Correct.

    // For n=1: special case, only number 1 starts and ends with 1, so 1.

    // Compute 18 * 10^(n-2)
    result := 18
    for i := 2; i < n; i++ {
        result *= 10
    }
    return result
}
