```go
package tri_test

import (
	"testing"
	"fmt"
)

// Everyone knows Fibonacci sequence, it was studied deeply by mathematicians in 
// the last couple centuries. However, what people don't know is Tribonacci sequence.
// Tribonacci sequence is defined by the recurrence:
// tri(1) = 3
// tri(n) = 1 + n / 2, if n is even.
// tri(n) =  tri(n - 1) + tri(n - 2) + tri(n + 1), if n is odd.
// For example:
// tri(2) = 1 + (2 / 2) = 2
// tri(4) = 3
// tri(3) = tri(2) + tri(1) + tri(4)
// = 2 + 3 + 3 = 8 
// You are given a non-negative integer number n, you have to a return a list of the 
// first n + 1 numbers of the Tribonacci sequence.
// Examples:
// >>> tri(3)
// []int{1, 3, 2, 8}
func tri(n int) []int {
	if n < 0 {
		return []int{}
	}

	// We need to compute tri(0), tri(1), ..., tri(n)
	// The problem says tri(1) = 3, tri(n) = 1 + n/2 for even n, and tri(n) = tri(n-1) + tri(n-2) + tri(n+1) for odd n.
	// But wait, the recurrence for odd n references tri(n+1), which creates a circular dependency.
	// Let's re-read the examples:
	// tri(1) = 3
	// tri(2) = 1 + 2/2 = 2
	// tri(4) = 1 + 4/2 = 3
	// tri(3) = tri(2) + tri(1) + tri(4) = 2 + 3 + 3 = 8
	// Result for n=3: []int{1, 3, 2, 8}
	// So tri(0) = 1, tri(1) = 3, tri(2) = 2, tri(3) = 8

	// It seems tri(0) = 1 is given implicitly.
	// For even n >= 2: tri(n) = 1 + n/2
	// For odd n >= 1: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
	// But tri(n+1) for odd n is even, so tri(n+1) = 1 + (n+1)/2

	// So for odd n: tri(n) = tri(n-1) + tri(n-2) + (1 + (n+1)/2)
	// where tri(n-1) and tri(n-2) are already computed if we go in order.

	// Let's verify:
	// tri(0) = 1
	// tri(1) = 3 (given)
	// tri(2) = 1 + 2/2 = 2
	// tri(3) = tri(2) + tri(1) + tri(4) = 2 + 3 + (1 + 4/2) = 2 + 3 + 3 = 8
	// tri(4) = 1 + 4/2 = 3
	// tri(5) = tri(4) + tri(3) + tri(6) = 3 + 8 + (1 + 6/2) = 3 + 8 + 4 = 15
	// tri(6) = 1 + 6/2 = 4

	// So the approach:
	// tri(0) = 1
	// tri(1) = 3
	// For even n >= 2: tri(n) = 1 + n/2
	// For odd n >= 3: tri(n) = tri(n-1) + tri(n-2) + (1 + (n+1)/2)

	if n == 0 {
		return []int{1}
	}

	result := make([]int, n+1)
	result[0] = 1
	result[1] = 3

	for i := 2; i <= n; i++ {
		if i%2 == 0 {
			result[i] = 1 + i/2
		} else {
			// i is odd and >= 3
			// tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
			// tri(i+1) is even, so tri(i+1) = 1 + (i+1)/2
			result[i] = result[i-1] + result[i-2] + (1 + (i+1)/2)
		}
	}

	return result
}
