func count_bidirectional(test_list [][]interface{}) int {
	// Count pairs where both [a, b] and [b, a] exist in the list
	// Each pair is counted once (not twice)
	pairSet := make(map[string]bool)
	count := 0

	for _, pair := range test_list {
		if len(pair) != 2 {
			continue
		}
		a := fmt.Sprintf("%v", pair[0])
		b := fmt.Sprintf("%v", pair[1])

		// Create a canonical key (sorted) to identify the pair regardless of order
		key1 := a + "|" + b
		key2 := b + "|" + a

		// If we've already seen the reverse, this is a bidirectional pair
		if pairSet[key2] {
			count++
			// Remove both to avoid double counting
			delete(pairSet, key1)
			delete(pairSet, key2)
		} else {
			pairSet[key1] = true
		}
	}

	return count
}
