// * all wells have the same length
// * 1 <= grid.length <= 10^2
// * 1 <= grid[:,1].length <= 10^2
// * grid[i][j] -> 0 | 1
// * 1 <= capacity <= 10
func max_fill(grid [][]int, capacity int) int {
    totalDrops := 0
    for _, well := range grid {
        waterUnits := 0
        for _, unit := range well {
            waterUnits += unit
        }
        if waterUnits > 0 {
            drops := waterUnits / capacity
            if waterUnits%capacity != 0 {
                drops++
            }
            totalDrops += drops
        }
    }
    return totalDrops
