// Write a gothon function to count minimum number of swaps required to convert one binary number represented as a string to another.
func min_Swaps(str1 string, str2 string) interface{} {
	if len(str1) != len(str2) {
		return fmt.Errorf("strings must be of the same length")
	}

	// Count mismatches where str1 has '0' and str2 has '1' (need to swap a 0 from str1 with a 1 from str1)
	// Actually, we need to think about this differently.
	// We want to transform str1 into str2 using swaps within str1.
	// A swap exchanges two characters in str1.
	// The minimum number of swaps to transform one binary string into another (when they have the same number of 1s and 0s) is related to the number of positions where they differ.

	// Let's count positions where str1[i] != str2[i]
	// Among these mismatched positions, some have str1[i]='0' and str2[i]='1' (call this count m01)
	// Others have str1[i]='1' and str2[i]='0' (call this count m10)
	// For a valid transformation, m01 must equal m10 (same number of 1s in both strings).
	// Each swap can fix at most 2 mismatches (one of each type).
	// So minimum swaps = m01 (which equals m10).

	m01 := 0
	m10 := 0

	for i := 0; i < len(str1); i++ {
		if str1[i] != str2[i] {
			if str1[i] == '0' && str2[i] == '1' {
				m01++
			} else if str1[i] == '1' && str2[i] == '0' {
				m10++
			}
		}
	}

	if m01 != m10 {
		return fmt.Errorf("cannot transform str1 to str2: different number of 1s")
	}

	return m01
}
