// >>> get_odd_collatz(5)
// []int{1, 5}
func get_odd_collatz(n int) []int {
	var oddNumbers []int
	for n != 1 {
		if n%2 != 0 {
			oddNumbers = append(oddNumbers, n)
		}
		if n%2 == 0 {
			n = n / 2
		} else {
			n = 3*n + 1
		}
	}
	// Don't forget to include 1
	oddNumbers = append(oddNumbers, 1)

	// Sort the odd numbers in increasing order
	for i := 0; i < len(oddNumbers); i++ {
		for j := i + 1; j < len(oddNumbers); j++ {
			if oddNumbers[i] > oddNumbers[j] {
				oddNumbers[i], oddNumbers[j] = oddNumbers[j], oddNumbers[i]
			}
		}
	}

	return oddNumbers
}
