// Write a function that takes in a list and an integer n, and re-arranges the first n elements of the given list so that all negative elements appear before positive ones, and where the relative order among negative and positive elements is preserved.
func re_arrange_array(arr []int, n int) []int {
    if n <= 0 || len(arr) == 0 {
        return arr
    }
    if n > len(arr) {
        n = len(arr)
    }

    // Extract the first n elements
    sub := make([]int, n)
    copy(sub, arr[:n])

    // Stable partition: negatives first, then positives, preserving relative order
    negatives := make([]int, 0, n)
    positives := make([]int, 0, n)

    for _, v := range sub {
        if v < 0 {
            negatives = append(negatives, v)
        } else {
            positives = append(positives, v)
        }
    }

    // Combine negatives and positives
    result := make([]int, n)
    copy(result, negatives)
    copy(result[len(negatives):], positives)

    // Copy back to the original array's first n elements
    copy(arr[:n], result)

    return arr
}
