// >>> int_to_mini_roman(426)
// "cdxxvi"
func int_to_mini_roman(number int) string {
	if number < 1 || number > 1000 {
		return ""
	}

	type romanPair struct {
		value  int
		symbol string
	}

	pairs := []romanPair{
		{1000, "M"},
		{900, "CM"},
		{500, "D"},
		{400, "CD"},
		{100, "C"},
		{90, "XC"},
		{50, "L"},
		{40, "XL"},
		{10, "X"},
		{9, "IX"},
		{5, "V"},
		{4, "IV"},
		{1, "I"},
	}

	result := ""
	for _, pair := range pairs {
		for number >= pair.value {
			result += pair.symbol
			number -= pair.value
		}
	}

	return result
}
