// Write a function to find the index of the first occurrence of a given number in a sorted list.
func find_first_occurrence(A []int, x int) int {
	// Binary search for the first occurrence of x in sorted array A
	left, right := 0, len(A)-1
	result := -1

	for left <= right {
		mid := left + (right-left)/2
		if A[mid] == x {
			result = mid
			// Continue searching in the left half to find the first occurrence
			right = mid - 1
		} else if A[mid] < x {
			left = mid + 1
		} else {
			right = mid - 1
		}
	}

	return result
}
