// This function takes a list l and returns a list l' such that
// l' is identical to l in the indicies that are not divisible by three, while its values at the indicies that are divisible by three are equal
// to the values of the corresponding indicies of l, but sorted.
// >>> sort_third([]int{1, 2, 3})
// []int{1, 2, 3}
// >>> sort_third([]int{5, 6, 3, 4, 8, 9, 2})
// []int{2, 6, 3, 4, 8, 9, 5}
func sort_third(l []int) []int {
	// Extract elements at indices divisible by 3
	var thirdElements []int
	for i := 0; i < len(l); i += 3 {
		thirdElements = append(thirdElements, l[i])
	}

	// Sort the extracted elements
	for i := 0; i < len(thirdElements); i++ {
		for j := i + 1; j < len(thirdElements); j++ {
			if thirdElements[i] > thirdElements[j] {
				thirdElements[i], thirdElements[j] = thirdElements[j], thirdElements[i]
			}
		}
	}

	// Place the sorted elements back into their original positions
	result := make([]int, len(l))
	copy(result, l)
	thirdIdx := 0
	for i := 0; i < len(l); i += 3 {
		result[i] = thirdElements[thirdIdx]
		thirdIdx++
	}

