package get_row_test

import (
	"testing"
	"fmt"
)

// You are given a 2 dimensional data, as a nested lists,
// which is similar to matrix, however, unlike matrices,
// each row may contain a different number of columns.
// Given lst, and integer x, find integers x in the list,
// and return list of lists, [(x1, y1), (x2, y2) ...] such that
// each list is a coordinate - (row, columns), starting with 0.
// Sort coordinates initially by rows in ascending order.
// Also, sort coordinates of the row by columns in descending order.
// Examples:
// >>> get_row([][]int{[]int{1, 2, 3, 4, 5, 6}, []int{1, 2, 3, 4, 1, 6}, []int{1, 2, 3, 4, 5, 1}}, 1)
// [][]int{[]interface{}{0, 0}, []interface{}{1, 4}, []interface{}{1, 0}, []interface{}{2, 5}, []interface{}{2, 0}}
// >>> get_row([][]int{}, 1)
// [][]interface{}{}
// >>> get_row([]interface{}{[]interface{}{}, []int{1}, []int{1, 2, 3}}, 3)
// [][]int{[]interface{}{2, 2}}
func get_row(lst [][]int, x int) [][]interface{} {
	var result [][]interface{}

	for row, innerSlice := range lst {
		for col, val := range innerSlice {
			if val == x {
				result = append(result, []interface{}{row, col})
			}
		}
	}

	// Sort by row ascending, then by column descending
	for i := 0; i < len(result); i++ {
		for j := i + 1; j < len(result); j++ {
			rowI := result[i][0].(int)
			rowJ := result[j][0].(int)
			colI := result[i][1].(int)
			colJ := result[j][1].(int)

			if rowI > rowJ || (rowI == rowJ && colI < colJ) {
				result[i], result[j] = result[j], result[i]
			}
		}
	}

	return result
}
