package shell_sort_test

import (
	"testing"
	"fmt"
)

// Write a function to sort the given list by using shell sort.
func shell_sort(my_list []int) []int {
	n := len(my_list)
	if n <= 1 {
		return my_list
	}

	// Start with a large gap, then reduce the gap
	gap := n / 2
	for gap > 0 {
		// Perform a gapped insertion sort for this gap size
		for i := gap; i < n; i++ {
			temp := my_list[i]
			j := i
			// Shift earlier gap-sorted elements up until the correct location for my_list[i] is found
			for j >= gap && my_list[j-gap] > temp {
				my_list[j] = my_list[j-gap]
				j -= gap
			}
			my_list[j] = temp
		}
		gap /= 2
	}

	return my_list
}
```

