// "Given a list representing a branch of a tree that has non-negative integer nodes
// your task is to pluck one of the nodes and return it.
// The plucked node should be the node with the smallest even value.
// If multiple nodes with the same smallest even value are found return the node that has smallest index.
// The plucked node should be returned in a list, [ smalest_value, its index ],
// If there are no even values or the given list is empty, return [].
// Example 1:
// >>> pluck([]int{4, 2, 3})
// []int{2, 1}
// Explanation: 2 has the smallest even value, and 2 has the smallest index.
// Example 2:
// >>> pluck([]int{1, 2, 3})
// []int{2, 1}
// Explanation: 2 has the smallest even value, and 2 has the smallest index.
// Example 3:
// >>> pluck([]int{})
// []int{}
// Example 4:
// >>> pluck([]int{5, 0, 3, 0, 4, 2})
// []int{0, 1}
// Explanation: 0 is the smallest value, but  there are two zeros,
// so we will choose the first zero, which has the smallest index.
// Constraints:
// * 1 <= nodes.length <= 10000
// * 0 <= node.value
func pluck(arr []int) []int {
	if len(arr) == 0 {
		return []int{}
	}

	smallestEven := -1
	smallestIndex := -1

	for i, val := range arr {
		if val%2 == 0 {
			if smallestEven == -1 || val < smallestEven {
				smallestEven = val
				smallestIndex = i
			}
		}
	}

	if smallestEven == -1 {
		return []int{}
	}

	return []int{smallestEven, smallestIndex}
}
