package sort_array_test

import (
	"testing"
	"fmt"
	"sort"
)

// In this Kata, you have to sort a list of non-negative integers according to
// number of ones in their binary representation in ascending order.
// For similar number of ones, sort based on decimal value.
// It must be implemented like this:
// >>> sort_array([]int{1, 5, 2, 3, 4})
// []int{1, 2, 3, 4, 5}
// >>> sort_array([]int{-2, -3, -4, -5, -6})
// []int{-6, -5, -4, -3, -2}
// >>> sort_array([]int{1, 0, 2, 3, 4})
// []int{0, 1, 2, 3, 4}
func sort_array(arr []int) []int {
	// Count the number of 1s in the binary representation of a non-negative integer
	countOnes := func(n int) int {
		count := 0
		for n > 0 {
			count += n & 1
			n >>= 1
		}
		return count
	}

	// Create a copy of the array to avoid modifying the original
	result := make([]int, len(arr))
	copy(result, arr)

	// Sort based on the number of ones, then by decimal value
	sort.Slice(result, func(i, j int) bool {
		onesI := countOnes(result[i])
		onesJ := countOnes(result[j])
		if onesI != onesJ {
			return onesI < onesJ
		}
		return result[i] < result[j]
	})

	return result
}
