package valid_date_test

import (
    "testing"
    "fmt"
)

// You have to write a function which validates a given date string and
// returns true if the date is valid otherwise false.
// The date is valid if all of the following rules are satisfied:
// 1. The date string is not empty.
// 2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
// 3. The months should not be less than 1 or higher than 12.
// 4. The date should be in the format: mm-dd-yyyy
// >>> valid_date("03-11-2000")
// true
// >>> valid_date("15-01-2012")
// false
// >>> valid_date("04-0-2040")
// false
// >>> valid_date("06-04-2020")
// true
// >>> valid_date("06/04/2020")
// false
func valid_date(date string) bool {
    if date == "" {
        return false
    }

    // Check format: mm-dd-yyyy
    parts := splitDate(date)
    if len(parts) != 3 {
        return false
    }

    monthStr := parts[0]
    dayStr := parts[1]
    yearStr := parts[2]

    // Check that each part has the correct number of digits
    if len(monthStr) != 2 || len(dayStr) != 2 || len(yearStr) != 4 {
        return false
    }

    // Parse month
    month, err := parseInt(monthStr)
    if err != nil {
        return false
    }

    // Parse day
    day, err := parseInt(dayStr)
    if err != nil {
        return false
    }

    // Parse year (we don't really need the year value for validation beyond format)
    _, err = parseInt(yearStr)
    if err != nil {
        return false
    }

    // Check month range
    if month < 1 || month > 12 {
        return false
    }

    // Check day range based on month
    maxDays := 0
    switch month {
    case 1, 3, 5, 7, 8, 10, 12:
        maxDays = 31
    case 4, 6, 9, 11:
        maxDays = 30
    case 2:
        maxDays = 29
    }

    if day < 1 || day > maxDays {
        return false
    }

    return true
}

func splitDate(date string) []string {
    var parts []string
    start := 0
    for i := 0; i < len(date); i++ {
        if date[i] == '-' {
            parts = append(parts, date[start:i])
            start = i + 1
        }
    }
    parts = append(parts, date[start:])
    return parts
}

func parseInt(s string) (int, error) {
    if len(s) == 0 {
        return 0, fmt.Errorf("empty string")
    }
    var result int
    for _, c := range s {
        if c < '0' || c > '9' {
            return 0, fmt.Errorf("invalid character")
        }
        result = result*10 + int(c-'0')
    }
    return result, nil
}
