// Write a gothon function to find a pair with highest product from a given list of integers.
func max_Product(arr []int) []interface{} {
	if len(arr) < 2 {
		return nil
	}

	// Find the pair with the highest product.
	// The highest product can come from either:
	// 1. The two largest numbers (both positive)
	// 2. The two smallest numbers (both negative, their product is positive and large)

	// Sort the array to easily find the largest and smallest elements
	sorted := make([]int, len(arr))
	copy(sorted, arr)

	// Simple sort (insertion sort for small arrays, or just use sort package)
	for i := 1; i < len(sorted); i++ {
		key := sorted[i]
		j := i - 1
		for j >= 0 && sorted[j] > key {
			sorted[j+1] = sorted[j]
			j--
		}
		sorted[j+1] = key
	}

	n := len(sorted)
	// Two candidates: two largest (last two) or two smallest (first two)
	product1 := sorted[n-1] * sorted[n-2] // two largest
	product2 := sorted[0] * sorted[1]     // two smallest

	if product1 >= product2 {
		return []interface{}{sorted[n-1], sorted[n-2]}
	} else {
		return []interface{}{sorted[0], sorted[1]}
	}
}
