// Write a gothon function to find the element that appears only once in a sorted list.
func search(arr []int) int {
	if len(arr) == 0 {
		panic("empty array")
	}

	left, right := 0, len(arr)-1

	for left < right {
		mid := left + (right-left)/2

		// Check if mid is even or odd to determine the pair
		if mid%2 == 0 {
			// If mid is even, the pair should be at mid+1
			if mid+1 < len(arr) && arr[mid] == arr[mid+1] {
				left = mid + 2
			} else {
				right = mid
			}
		} else {
			// If mid is odd, the pair should be at mid-1
			if arr[mid] == arr[mid-1] {
				left = mid + 1
			} else {
				right = mid - 1
			}
		}
	}

	return arr[left]
}
