// >>> modp(0, 101)
// 1
// >>> modp(3, 11)
// 8
// >>> modp(100, 101)
// 1
func modp(n int, p int) int {
	if p == 1 {
		return 0
	}
	if n == 0 {
		return 1 % p
	}
	result := 1
	base := 2 % p
	for n > 0 {
		if n&1 == 1 {
			result = (result * base) % p
		}
		base = (base * base) % p
		n >>= 1
	}
	return result
}
