package file_name_check_test

import (
	"strings"
	"unicode"
)

// Create a function which takes a string representing a file's name, and returns
// 'Yes' if the the file's name is valid, and returns 'No' otherwise.
// A file's name is considered to be valid if and only if all the following conditions 
// are met:
// - There should not be more than three digits ('0'-'9') in the file's name.
// - The file's name contains exactly one dot '.'
// - The substring before the dot should not be empty, and it starts with a letter from 
// the latin alphapet ('a'-'z' and 'A'-'Z').
// - The substring after the dot should be one of these: ['txt', 'exe', 'dll']
// Examples:
// >>> file_name_check("example.txt")
// "Yes"
// >>> file_name_check("1example.dll")
// "No"
func file_name_check(file_name string) string {
	// Check for exactly one dot
	dotCount := strings.Count(file_name, ".")
	if dotCount != 1 {
		return "No"
	}

	// Split into name and extension
	dotIndex := strings.Index(file_name, ".")
	beforeDot := file_name[:dotIndex]
	afterDot := file_name[dotIndex+1:]

	// Check that the substring before the dot is not empty
	if len(beforeDot) == 0 {
		return "No"
	}

	// Check that the substring before the dot starts with a letter
	if !unicode.IsLetter(rune(beforeDot[0])) {
		return "No"
	}

	// Check that the substring after the dot is one of ['txt', 'exe', 'dll']
	if afterDot != "txt" && afterDot != "exe" && afterDot != "dll" {
		return "No"
	}

	// Check that there are not more than three digits in the file's name
	digitCount := 0
	for _, ch := range file_name {
		if unicode.IsDigit(ch) {
			digitCount++
		}
	}
	if digitCount > 3 {
		return "No"
	}

	return "Yes"
}
