```go
package simplify_test

import (
	"testing"
	"fmt"
)

// Your task is to implement a function that will simplify the expression
// x * n. The function returns true if x * n evaluates to a whole number and false
// otherwise. Both x and n, are string representation of a fraction, and have the following format,
// <numerator>/<denominator> where both numerator and denominator are positive whole numbers.
// You can assume that x, and n are valid fractions, and do not have zero as denominator.
// >>> simplify("1/5", "5/1")
// true
// >>> simplify("1/6", "2/1")
// false
// >>> simplify("7/10", "10/2")
// false
func simplify(x string, n string) bool {
	// Parse x = xNum/xDen
	xParts := splitFraction(x)
	xNum := xParts[0]
	xDen := xParts[1]

	// Parse n = nNum/nDen
	nParts := splitFraction(n)
	nNum := nParts[0]
	nDen := nParts[1]

	// x * n = (xNum * nNum) / (xDen * nDen)
	// We need to check if this is a whole number, i.e., (xNum * nNum) % (xDen * nDen) == 0
	// But we should simplify the fraction first to avoid overflow and for correctness.

	// Compute numerator and denominator of the product
	num := xNum * nNum
	den := xDen * nDen

	// Simplify by dividing by GCD
	g := gcd(num, den)
	num = num / g
	den = den / g

	// Check if denominator is 1
	return den == 1
}

func splitFraction(s string) [2]int {
	// Find the slash
	for i, c := range s {
		if c == '/' {
			numStr := s[:i]
			denStr := s[i+1:]
			var num, den int
			fmt.Sscanf(numStr, "%d", &num)
			fmt.Sscanf(denStr, "%d", &den)
			return [2]int{num, den}
		}
	}
	return [2]int{0, 1}
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
