// Write a gothon function to count the number of rotations required to generate a sorted list. https://www.geeksforgeeks.org/count-of-rotations-required-to-generate-a-sorted-list/
func count_rotation(arr []int) int {
	if len(arr) == 0 {
		return 0
	}

	n := len(arr)
	if arr[0] <= arr[n-1] {
		return 0
	}

	left, right := 0, n-1
	for left <= right {
		if arr[left] <= arr[right] {
			return left
		}

		mid := left + (right-left)/2
		next := (mid + 1) % n
		prev := (mid - 1 + n) % n

		if arr[mid] <= arr[next] && arr[mid] <= arr[prev] {
			return mid
		}

		if arr[mid] <= arr[right] {
			right = mid - 1
		} else {
			left = mid + 1
		}
	}

	return 0
}
