// Write a function to find the specified number of largest products from two given lists, selecting one factor from each list.
func large_product(nums1 []int, nums2 []int, N int) []int {
	// Generate all possible products
	products := make([]int, 0, len(nums1)*len(nums2))
	for _, n1 := range nums1 {
		for _, n2 := range nums2 {
			products = append(products, n1*n2)
		}
	}

	// Sort products in descending order
	for i := 0; i < len(products); i++ {
		for j := i + 1; j < len(products); j++ {
			if products[j] > products[i] {
				products[i], products[j] = products[j], products[i]
			}
		}
	}

	// Take the top N products
	if N > len(products) {
		N = len(products)
	}
	return products[:N]
}
