package anti_shuffle_test

import (
	"strings"
	"sort"
	"unicode"
)

// Write a function that takes a string and returns an ordered version of it.
// Ordered version of string, is a string where all words (separated by space)
// are replaced by a new word where all the characters arranged in
// ascending order based on ascii value.
// Note: You should keep the order of words and blank spaces in the sentence.
// For example:
// >>> anti_shuffle("Hi")
// "Hi"
// >>> anti_shuffle("hello")
// "ehllo"
// >>> anti_shuffle("Hello World!!!")
// "Hello !!!Wdlor"
func anti_shuffle(s string) string {
	// Split the string into words and spaces, preserving all characters
	// We need to process each "word" (sequence of non-space characters) and sort their characters
	// while keeping spaces in place.

	// Approach: iterate through the string, identify words (non-space sequences),
	// sort the characters in each word, and keep spaces as-is.

	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == ' ' {
			result.WriteByte(' ')
			i++
		} else {
			// Collect a word
			start := i
			for i < len(s) && s[i] != ' ' {
				i++
			}
			word := s[start:i]
			// Sort the characters in the word by ASCII value
			runes := []rune(word)
			sort.Slice(runes, func(a, b int) bool {
				return runes[a] < runes[b]
			})
			result.WriteString(string(runes))
		}
	}
	return result.String()
}
