// Write a gothon function that takes in a non-negative number and returns the number of prime numbers less than the given non-negative number.
func count_Primes_nums(n int) int {
	if n <= 2 {
		return 0
	}

	// Sieve of Eratosthenes
	isPrime := make([]bool, n)
	for i := 2; i < n; i++ {
		isPrime[i] = true
	}

	for i := 2; i*i < n; i++ {
		if isPrime[i] {
			for j := i * i; j < n; j += i {
				isPrime[j] = false
			}
		}
	}

	count := 0
	for i := 2; i < n; i++ {
		if isPrime[i] {
			count++
		}
	}
	return count
}
